// ─── File: RateLimitDemo.java ───
// Multi-level limits + per-provider token buckets with clean failover.
// Each class below would be its own file in a real project.
package com.bank.rl;

import java.util.logging.*;

public class RateLimitDemo {

    private static final Logger log = Logger.getLogger("RL");

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        handler.setLevel(Level.ALL);
        log.setUseParentHandlers(false);
        log.addHandler(handler);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        LayeredLimiter limiter = new LayeredLimiter();
        ProviderRouter router = new ProviderRouter();

        // Legitimate: Rajesh sends a few — passes all levels, routed to primary.
        for (int i = 0; i < 3; i++) attempt(limiter, router, "RAJESH", "10.1.1.9");

        // Per-user catches Rajesh's 4th → rejected (others unaffected).
        attempt(limiter, router, "RAJESH", "10.1.1.9");

        // Per-IP catches one source hitting many accounts (global stays blind to who).
        for (int i = 0; i < 22; i++) attempt(limiter, router, "USER" + i, "66.66.66.66");

        // Drain the PRIMARY provider bucket → clean FAILOVER to secondary (no hammering).
        log.info("── draining primary provider to force failover ──");
        for (int i = 0; i < 8; i++) router.send("BULK" + i);
    }

    static void attempt(LayeredLimiter limiter, ProviderRouter router, String user, String ip) {
        LayeredLimiter.Decision d = limiter.check(user, ip);
        if (!d.allowed) { log.warning(() -> d.level + " limit → " + d.action + " (" + user + "/" + ip + ")"); return; }
        router.send(user);
    }
}

// ─── limiter/LayeredLimiter.java ───  per-user → per-IP → global, each a different pattern
class LayeredLimiter {
    static class Decision { boolean allowed; String level, action;
        Decision(boolean a, String l, String ac){ allowed=a; level=l; action=ac; } }

    private final java.util.Map<String, Integer> userCount = new java.util.concurrent.ConcurrentHashMap<>();
    private final java.util.Map<String, Integer> ipCount = new java.util.concurrent.ConcurrentHashMap<>();
    private int globalCount = 0;

    // A request must pass ALL applicable levels; each catches what the others can't.
    synchronized Decision check(String user, String ip) {
        if (userCount.merge(user, 1, Integer::sum) > 3)                 // one account flooding
            return new Decision(false, "PER-USER", "REJECT");
        if (ipCount.merge(ip, 1, Integer::sum) > 20)                   // one source, many accounts
            return new Decision(false, "PER-IP", "CAPTCHA");
        if (++globalCount > 100000)                                     // system-wide flood backstop
            return new Decision(false, "GLOBAL", "SHED");
        return new Decision(true, "OK", "ALLOW");
    }
}

// ─── limiter/TokenBucket.java ───  models ONE downstream's live headroom
class TokenBucket {
    private final String name; private final int capacity; private final double refillPerSec;
    private double tokens; private long lastRefill = System.nanoTime();

    TokenBucket(String name, int capacity, double refillPerSec) {
        this.name = name; this.capacity = capacity; this.refillPerSec = refillPerSec; this.tokens = capacity;
    }
    synchronized boolean tryConsume() {
        refill();
        if (tokens >= 1) { tokens -= 1; return true; }
        return false;                                  // empty → caller should FAIL OVER, not retry here
    }
    private void refill() {
        long now = System.nanoTime();
        tokens = Math.min(capacity, tokens + (now - lastRefill) / 1e9 * refillPerSec);
        lastRefill = now;
    }
    String name() { return name; }
    double available() { return tokens; }
}

// ─── route/ProviderRouter.java ───  bucket PER provider → clean failover
class ProviderRouter {
    private static final Logger log = Logger.getLogger("RL");
    // ordered list; each with its OWN bucket (NOT one shared limiter)
    private final java.util.List<TokenBucket> providers = java.util.List.of(
            new TokenBucket("SMS-PRIMARY", 5, 5),
            new TokenBucket("SMS-SECONDARY", 3, 3));

    void send(String target) {
        for (TokenBucket p : providers) {
            if (p.tryConsume()) {                       // route to the first provider WITH tokens
                log.info(() -> "sent " + target + " via " + p.name() + " (tokens left " + String.format("%.1f", p.available()) + ")");
                return;
            }
            log.warning(() -> p.name() + " bucket EMPTY → fail over (NOT hammering it)");  // informed failover
        }
        log.severe(() -> "all provider buckets empty → queue/TTL-shed for " + target);
    }
}

class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT %2$-7s %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
